import hmac,json,os
from contextlib import asynccontextmanager
from pathlib import Path
import joblib,numpy as np
from fastapi import FastAPI,HTTPException,Header,Depends
from pydantic import BaseModel,ConfigDict,Field,field_validator
from features import NAMES,SCHEMA
import workspace

ROOT=Path(__file__).resolve().parent
bundle=None
@asynccontextmanager
async def lifespan(app):
    global bundle
    workspace.recover_jobs()
    path=ROOT/'artifacts'/'model.joblib'
    if path.exists():
        # Only load artifacts generated by the trusted offline pipeline.
        candidate=joblib.load(path)
        if candidate['metadata']['featureSchemaVersion']!=SCHEMA or candidate['metadata']['featureNames']!=NAMES:raise RuntimeError('Incompatible model schema')
        bundle=candidate
    yield

app=FastAPI(title='FraudShield AI Inference',version='1.0.0',lifespan=lifespan,docs_url='/docs' if os.getenv('APP_ENV','development')=='development' else None)
def verify(x_service_key:str=Header(default='')):
    key=os.getenv('AI_SERVICE_KEY')
    if not key or not key.strip():
        if os.getenv('APP_ENV','development')!='development':raise HTTPException(503,'Service key not configured')
        key='local-ai-service-key'
    if not hmac.compare_digest(key.encode(),x_service_key.encode()):raise HTTPException(401,'Invalid service key')

app.include_router(workspace.router, dependencies=[Depends(verify)])

class Features(BaseModel):
    model_config=ConfigDict(extra='forbid',allow_inf_nan=False)
    amount:float=Field(gt=0,le=1e11)
    transactionCount1h:float=Field(ge=0)
    transactionCount24h:float=Field(ge=0)
    amountZScore:float=Field(ge=-10,le=10)
    isNewDevice:float=Field(ge=0,le=1)
    isNewLocation:float=Field(ge=0,le=1)
    sharedDeviceUsers:float=Field(ge=0)
    sharedIpUsers:float=Field(ge=0)
    hourOfDay:float=Field(ge=0,le=23)
    merchantRisk:float=Field(ge=0,le=1)
class PredictRequest(BaseModel):
    model_config=ConfigDict(extra='forbid')
    transactionId:str=Field(min_length=1,max_length=80)
    featureSchemaVersion:str
    features:Features

@app.get('/health')
def health():
    if bundle is None:raise HTTPException(503,'No trained model. Run train.py offline, then restart the service.')
    return {'status':'ready','modelVersion':bundle['metadata']['modelVersion'],'featureSchemaVersion':SCHEMA}
@app.post('/v1/predict',dependencies=[Depends(verify)])
def predict(req:PredictRequest):
    if req.featureSchemaVersion!=SCHEMA:raise HTTPException(422,'Unsupported feature schema')
    if bundle is None:raise HTTPException(503,'Model not loaded')
    f=req.features.model_dump();score=float(bundle['model'].predict_proba(np.array([[f[k] for k in NAMES]]))[0,1])
    return dict(transactionId=req.transactionId,score=score,modelVersion=bundle['metadata']['modelVersion'],featureSchemaVersion=SCHEMA)
@app.get('/v1/metrics',dependencies=[Depends(verify)])
def metrics():
    if bundle is None:raise HTTPException(503,'Model not loaded')
    return bundle['metadata']
